use std::path::PathBuf;
use clap::{Parser, Subcommand};
use std::env;

mod db;
mod commands;
mod format;
mod scan;

use commands::*;

#[derive(Parser)]
#[command(name = "duc")]
#[command(about = "index, query and graph disk usage", version = "1.5.0-rc1")]
#[command(subcommand_required = false)]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

    #[arg(global = true, long)]
    version: bool,

    #[arg(global = true, short, long)]
    help: bool,

    #[arg(global = true, short, long)]
    verbose: bool,

    #[arg(global = true, short, long)]
    quiet: bool,

    #[arg(global = true, long)]
    debug: bool,

    #[arg(long)]
    database: Option<PathBuf>,

    #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
    args: Vec<String>,
}

#[derive(Subcommand)]
enum Commands {
    Help { subcommand: Option<String>, #[arg(long)] all: bool },
    Index(IndexCmd),
    Info(InfoCmd),
    Ls(LsCmd),
    Topn(TopnCmd),
    Xml(XmlCmd),
    Json(JsonCmd),
    Histogram(HistogramCmd),
    Graph(GraphCmd),
    Cgi(CgiCmd),
    Gui(GuiCmd),
    Ui(UiCmd),
}

fn main() {
    let args: Vec<String> = env::args().collect();

    // Handle old-style command: duc <cmd> [options]
    if args.len() > 1 && !args[1].starts_with("-") {
        let cmd = &args[1];
        match cmd {
            "help" | "index" | "info" | "ls" | "topn" | "xml" | "json" 
            | "histogram" | "graph" | "cgi" | "gui" | "ui" => {
                handle_command(&args);
                return;
            }
            "--version" => {
                println!("duc version: 1.5.0-rc1");
                println!("options: cairo x11 ui sqlite3");
                return;
            }
            "--help" => {
                print_usage();
                return;
            }
            _ => {}
        }
    }

    // If no command provided or --help/--version at start
    if args.len() == 1 {
        print_usage();
        return;
    }

    let cli = Cli::parse();

    if cli.version {
        println!("duc version: 1.5.0-rc1");
        println!("options: cairo x11 ui sqlite3");
        return;
    }

    if cli.help && cli.command.is_none() {
        print_usage();
        return;
    }

    match cli.command {
        Some(Commands::Help { subcommand, all }) => {
            commands::help::print_help(subcommand, all);
        }
        Some(Commands::Index(cmd)) => {
            if let Err(e) = commands::index::run(cmd, cli.database) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        Some(Commands::Info(cmd)) => {
            if let Err(e) = commands::info::run(cmd, cli.database) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        Some(Commands::Ls(cmd)) => {
            if let Err(e) = commands::ls::run(cmd, cli.database) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        Some(Commands::Topn(cmd)) => {
            if let Err(e) = commands::topn::run(cmd, cli.database) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        Some(Commands::Xml(cmd)) => {
            if let Err(e) = commands::xml::run(cmd, cli.database) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        Some(Commands::Json(cmd)) => {
            if let Err(e) = commands::json::run(cmd, cli.database) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        Some(Commands::Histogram(cmd)) => {
            if let Err(e) = commands::histogram::run(cmd, cli.database) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        Some(Commands::Graph(_)) => {
            eprintln!("Graph command not implemented");
            std::process::exit(1);
        }
        Some(Commands::Cgi(_)) => {
            eprintln!("CGI command not implemented");
            std::process::exit(1);
        }
        Some(Commands::Gui(_)) => {
            eprintln!("GUI command not implemented");
            std::process::exit(1);
        }
        Some(Commands::Ui(_)) => {
            eprintln!("UI command not implemented");
            std::process::exit(1);
        }
        None => {
            print_usage();
        }
    }
}

fn print_usage() {
    println!("usage: duc <cmd> [options] [args]\n");
    println!("Available subcommands:\n");
    println!("  help      : Show help");
    println!("  histogram : Dump histogram of file sizes found.");
    println!("  index     : Scan the filesystem and generate the Duc index");
    println!("  info      : Dump database info");
    println!("  ls        : List sizes of directory");
    println!("  topn      : Dump N largest files in DB.");
    println!("  xml       : Dump XML output");
    println!("  json      : Dump JSON output");
    println!("  graph     : Generate a sunburst graph for a given path");
    println!("  cgi       : CGI interface wrapper");
    println!("  gui       : Interactive X11 graphical interface");
    println!("  ui        : Interactive ncurses user interface\n");
    println!("Global options:");
    println!("       --debug               increase verbosity to debug level");
    println!("  -h,  --help                show help");
    println!("  -q,  --quiet               quiet mode, do not print any warning");
    println!("  -v,  --verbose             increase verbosity");
    println!("       --version             output version information and exit\n");
    println!("Use 'duc help <subcommand>' or 'duc <subcommand> -h' for a complete list of all");
    println!("options and detailed description of the subcommand.\n");
    println!("Use 'duc help --all' for a complete list of all options for all subcommands.");
}

