    let cmd = &args[1];

    match cmd {
        "help" => {
            let subcommand = args.get(2).map(|s| s.as_str());
            let all = args.contains(&"--all".to_string());
            commands::help::print_help(subcommand.map(|s| s.to_string()), all);
        }
        "index" => {
            let cmd = IndexCmd::parse_args(&args[1..]);
            if let Err(e) = commands::index::run(cmd, None) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        "info" => {
            let cmd = InfoCmd::parse_args(&args[1..]);
            if let Err(e) = commands::info::run(cmd, None) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        "ls" => {
            let cmd = LsCmd::parse_args(&args[1..]);
            if let Err(e) = commands::ls::run(cmd, None) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        "topn" => {
            let cmd = TopnCmd::parse_args(&args[1..]);
            if let Err(e) = commands::topn::run(cmd, None) {
