                std::process::exit(1);
            }
        }
        "json" => {
            let cmd = JsonCmd::parse_args(&args[1..]);
            if let Err(e) = commands::json::run(cmd, None) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        "histogram" => {
            let cmd = HistogramCmd::parse_args(&args[1..]);
            if let Err(e) = commands::histogram::run(cmd, None) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        "graph" => {
            eprintln!("Graph command not yet implemented");
