struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

    #[arg(global = true, long)]
    version: bool,

    #[arg(global = true, short, long)]
    help: bool,

    #[arg(global = true, short, long)]
    verbose: bool,

    #[arg(global = true, short, long)]
    quiet: bool,

