    database: Option<PathBuf>,

    #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
    args: Vec<String>,
}

#[derive(Subcommand)]
enum Commands {
    Help { subcommand: Option<String>, #[arg(long)] all: bool },
    Index(IndexCmd),
    Info(InfoCmd),
    Ls(LsCmd),
    Topn(TopnCmd),
    Xml(XmlCmd),
    Json(JsonCmd),
    Histogram(HistogramCmd),
    Graph(GraphCmd),
    Cgi(CgiCmd),
    Gui(GuiCmd),
    Ui(UiCmd),
}

fn main() {
    let args: Vec<String> = env::args().collect();

    // Handle old-style command: duc <cmd> [options]
    if args.len() > 1 && !args[1].starts_with("-") {
        let cmd = &args[1];
        match cmd {
            "help" | "index" | "info" | "ls" | "topn" | "xml" | "json" 
            | "histogram" | "graph" | "cgi" | "gui" | "ui" => {
