            "--help" => {
                print_usage();
                return;
            }
            _ => {}
        }
    }

    // If no command provided or --help/--version at start
    if args.len() == 1 {
        print_usage();
        return;
    }

    let cli = Cli::parse();

    if cli.version {
        println!("duc version: 1.5.0-rc1");
        println!("options: cairo x11 ui sqlite3");
        return;
