use rusqlite::{Connection, Result, params};
use std::path::PathBuf;
use chrono::Local;

#[derive(Debug, Clone)]
pub struct DirEntry {
    pub path: String,
    pub size_actual: u64,
    pub size_apparent: u64,
    pub count: u64,
    pub files: u64,
    pub dirs: u64,
    pub mtime: u64,
}

pub struct Database {
    conn: Connection,
}

impl Database {
    pub fn open(path: &PathBuf) -> Result<Self> {
        let conn = Connection::open(path)?;
        conn.execute_batch(
            "CREATE TABLE IF NOT EXISTS \"directory\" (
                path TEXT PRIMARY KEY,
                size_actual INTEGER,
                size_apparent INTEGER,
                count INTEGER,
                files INTEGER,
                dirs INTEGER,
                mtime INTEGER
            );",
        )?;

        conn.execute_batch(
            "CREATE TABLE IF NOT EXISTS \"file\" (
                path TEXT PRIMARY KEY,
                size_actual INTEGER,
                size_apparent INTEGER
            );",
        )?;

        conn.execute_batch(
            "CREATE TABLE IF NOT EXISTS \"index\" (
                name TEXT PRIMARY KEY,
                value TEXT
            );",
        )?;

        Ok(Database { conn })
    }

    pub fn insert_dir(&self, entry: &DirEntry) -> Result<()> {
        self.conn.execute(
            "INSERT OR REPLACE INTO directory (path, size_actual, size_apparent, count, files, dirs, mtime)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
            params![
                &entry.path,
                entry.size_actual,
                entry.size_apparent,
                entry.count,
                entry.files,
                entry.dirs,
                entry.mtime,
            ],
        )?;
        Ok(())
    }

    pub fn insert_file(&self, path: &str, size_actual: u64, size_apparent: u64) -> Result<()> {
        self.conn.execute(
            "INSERT OR REPLACE INTO file (path, size_actual, size_apparent) VALUES (?1, ?2, ?3)",
            params![path, size_actual, size_apparent],
        )?;
        Ok(())
    }

    pub fn get_dir(&self, path: &str) -> Result<Option<DirEntry>> {
        let mut stmt = self.conn.prepare(
            "SELECT path, size_actual, size_apparent, count, files, dirs, mtime FROM directory WHERE path = ?1",
        )?;
        let result = stmt.query_row(params![path], |row| {
            Ok(DirEntry {
                path: row.get(0)?,
                size_actual: row.get(1)?,
                size_apparent: row.get(2)?,
                count: row.get(3)?,
                files: row.get(4)?,
                dirs: row.get(5)?,
                mtime: row.get(6)?,
            })
        });

        match result {
            Ok(entry) => Ok(Some(entry)),
            Err(rusqlite::Error::QueryReturnedNoRows) => Ok(None),
            Err(e) => Err(e),
        }
    }

    pub fn get_children(&self, path: &str) -> Result<Vec<DirEntry>> {
        let prefix = if path.ends_with("/") {
            path.to_string()
        } else {
            format!("{}/", path)
        };

        let mut stmt = self.conn.prepare(
            "SELECT path, size_actual, size_apparent, count, files, dirs, mtime FROM directory WHERE path LIKE ?1 || '%' AND path != ?1 ORDER BY path",
        )?;

        let entries = stmt.query_map(params![prefix], |row| {
            Ok(DirEntry {
                path: row.get(0)?,
                size_actual: row.get(1)?,
                size_apparent: row.get(2)?,
                count: row.get(3)?,
                files: row.get(4)?,
                dirs: row.get(5)?,
                mtime: row.get(6)?,
            })
        })?;

        let mut result = Vec::new();
        for entry in entries {
            result.push(entry?);
        }
        Ok(result)
    }

    pub fn get_direct_children(&self, path: &str) -> Result<Vec<DirEntry>> {
        let prefix = if path.ends_with("/") {
            path.to_string()
        } else {
            format!("{}/", path)
        };

        let mut stmt = self.conn.prepare(
            "SELECT path, size_actual, size_apparent, count, files, dirs, mtime FROM directory WHERE path LIKE ?1 || '%' AND path != ?1"
        )?;

        let entries = stmt.query_map(params![prefix], |row| {
            Ok(DirEntry {
                path: row.get(0)?,
                size_actual: row.get(1)?,
                size_apparent: row.get(2)?,
                count: row.get(3)?,
                files: row.get(4)?,
                dirs: row.get(5)?,
                mtime: row.get(6)?,
            })
        })?;

        let mut result = Vec::new();
        for entry in entries {
            let entry = entry?;
            // Only keep immediate children
            let rel_path = &entry.path[prefix.len()..];
            if !rel_path.contains('/') {
                result.push(entry);
            }
        }
        Ok(result)
    }

    pub fn get_all_entries(&self) -> Result<Vec<(String, u64, u64)>> {
        let mut stmt = self.conn.prepare(
            "SELECT path, size_actual, size_apparent FROM directory ORDER BY path",
        )?;

        let entries = stmt.query_map([], |row| {
            Ok((row.get(0)?, row.get(1)?, row.get(2)?))
        })?;

        let mut result = Vec::new();
        for entry in entries {
            result.push(entry?);
        }
        Ok(result)
    }

    pub fn get_top_files(&self) -> Result<Vec<(String, u64)>> {
        let mut stmt = self.conn.prepare(
            "SELECT path, size_actual FROM file ORDER BY size_actual DESC LIMIT 100",
        )?;

        let entries = stmt.query_map([], |row| Ok((row.get(0)?, row.get(1)?)))?;

        let mut result = Vec::new();
        for entry in entries {
            result.push(entry?);
        }
        Ok(result)
    }

    pub fn set_index_value(&self, name: &str, value: &str) -> Result<()> {
        self.conn.execute(
            "INSERT OR REPLACE INTO index (name, value) VALUES (?1, ?2)",
            params![name, value],
        )?;
        Ok(())
    }

    pub fn get_index_value(&self, name: &str) -> Result<Option<String>> {
        let mut stmt = self.conn.prepare("SELECT value FROM index WHERE name = ?1")?;
        let result = stmt.query_row(params![name], |row| row.get(0));

        match result {
            Ok(value) => Ok(Some(value)),
            Err(rusqlite::Error::QueryReturnedNoRows) => Ok(None),
            Err(e) => Err(e),
        }
    }

    pub fn clear(&self) -> Result<()> {
        self.conn.execute_batch("DELETE FROM directory; DELETE FROM file; DELETE FROM index;")?;
        Ok(())
    }
}
