use std::path::PathBuf;
use std::collections::HashMap;
use walkdir::WalkDir;
use crate::db::DirEntry;

#[derive(Debug, Clone)]
pub struct ScanResult {
    pub dirs: HashMap<PathBuf, (u64, u64, u64, u64)>, // (size_actual, size_apparent, count, files)
}

pub fn scan_directory(root: &PathBuf) -> std::io::Result<ScanResult> {
    let mut dirs: HashMap<PathBuf, (u64, u64, u64, u64)> = HashMap::new();

    // Add root
    dirs.insert(root.clone(), (0, 0, 0, 0));

    for entry in WalkDir::new(root)
        .into_iter()
        .filter_map(|e| e.ok())
    {
        let path = entry.path();
        if path == root {
            continue;
        }

        let metadata = match entry.metadata() {
            Ok(m) => m,
            Err(_) => continue,
        };

        let size = metadata.len();
        let apparent_size = if metadata.is_dir() { 4096 } else { ((size + 4095) / 4096) * 4096 };

        // Add this entry
        if metadata.is_dir() {
            dirs.insert(path.to_path_buf(), (0, 0, 0, 0));
        }

        // Update all parent directories
        let mut current = path.to_path_buf();
        while current.pop() {
            if current.starts_with(root) || current == root {
                let entry = dirs.entry(current.clone()).or_insert((0, 0, 0, 0));
                entry.0 += size;
                entry.1 += apparent_size;
                entry.2 += 1;
                if !metadata.is_dir() {
                    entry.3 += 1;
                }
            }
        }

        // Update root
        let entry = dirs.entry(root.clone()).or_insert((0, 0, 0, 0));
        entry.0 += size;
        entry.1 += apparent_size;
        entry.2 += 1;
        if !metadata.is_dir() {
            entry.3 += 1;
        }
    }

    Ok(ScanResult { dirs })
}
