pub fn format_size(bytes: u64, bytes_flag: bool) -> String {
    if bytes_flag {
        format!("{}", bytes)
    } else {
        let sizes = ["", "K", "M", "G", "T", "P"];
        let mut size = bytes as f64;
        let mut idx = 0;

        while size >= 1024.0 && idx < sizes.len() - 1 {
            size /= 1024.0;
            idx += 1;
        }

        if idx == 0 {
            format!("{:.1}", size).trim_end_matches(".0").to_string()
        } else if size >= 10.0 {
            format!("{:.0}{}", size, sizes[idx])
        } else {
            format!("{:.1}{}", size, sizes[idx]).trim_end_matches(".0").to_string()
        }
    }
}

pub fn pad_right(s: &str, width: usize) -> String {
    format!("{:<width$}", s, width = width)
}

pub fn pad_left(s: &str, width: usize) -> String {
    format!("{:>width$}", s, width = width)
}
