use crate::commands::{IndexCmd, ParseArgs};
use crate::db::{Database, DirEntry};
use crate::scan;
use std::path::{Path, PathBuf};
use chrono::Local;

impl ParseArgs for IndexCmd {
    fn parse_args(args: &[String]) -> Self {
        let mut cmd = IndexCmd {
            bytes: false,
            buckets: None,
            database: None,
            exclude: None,
            check_hard_links: false,
            force: false,
            fs_exclude: None,
            fs_include: None,
            hide_file_names: false,
            uid: None,
            topn: None,
            topn_min: None,
            username: None,
            max_depth: None,
            one_file_system: false,
            progress: false,
            dry_run: false,
            uncompressed: false,
            paths: Vec::new(),
        };

        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "-b" | "--bytes" => cmd.bytes = true,
                "-B" | "--buckets" => {
                    i += 1;
                    if i < args.len() {
                        cmd.buckets = Some(args[i].clone());
                    }
                }
                "-d" | "--database" => {
                    i += 1;
                    if i < args.len() {
                        cmd.database = Some(PathBuf::from(&args[i]));
                    }
                }
                "-e" | "--exclude" => {
                    i += 1;
                    if i < args.len() {
                        cmd.exclude = Some(args[i].clone());
                    }
                }
                "-H" | "--check-hard-links" => cmd.check_hard_links = true,
                "-f" | "--force" => cmd.force = true,
                "--fs-exclude" => {
                    i += 1;
                    if i < args.len() {
                        cmd.fs_exclude = Some(args[i].clone());
                    }
                }
                "--fs-include" => {
                    i += 1;
                    if i < args.len() {
                        cmd.fs_include = Some(args[i].clone());
                    }
                }
                "--hide-file-names" => cmd.hide_file_names = true,
                "-U" | "--uid" => {
                    i += 1;
                    if i < args.len() {
                        cmd.uid = Some(args[i].clone());
                    }
                }
                "-T" | "--topn" => {
                    i += 1;
                    if i < args.len() {
                        cmd.topn = args[i].parse().ok();
                    }
                }
                "-M" | "--topn-min" => {
                    i += 1;
                    if i < args.len() {
                        cmd.topn_min = args[i].parse().ok();
                    }
                }
                "-u" | "--username" => {
                    i += 1;
                    if i < args.len() {
                        cmd.username = Some(args[i].clone());
                    }
                }
                "-m" | "--max-depth" => {
                    i += 1;
                    if i < args.len() {
                        cmd.max_depth = args[i].parse().ok();
                    }
                }
                "-x" | "--one-file-system" => cmd.one_file_system = true,
                "-p" | "--progress" => cmd.progress = true,
                "--dry-run" => cmd.dry_run = true,
                "--uncompressed" => cmd.uncompressed = true,
                _ => {
                    if !args[i].starts_with("-") {
                        cmd.paths.push(PathBuf::from(&args[i]));
                    }
                }
            }
            i += 1;
        }

        cmd
    }
}

pub fn run(mut cmd: IndexCmd, global_db: Option<PathBuf>) -> Result<(), Box<dyn std::error::Error>> {
    if cmd.paths.is_empty() {
        return Err("No paths specified".into());
    }

    // Get database path
    let db_path = if let Some(db) = cmd.database.take() {
        db
    } else if let Some(db) = global_db {
        db
    } else {
        let mut path = dirs::home_dir().ok_or("Could not find home directory")?;
        path.push(".cache");
        path.push("duc");
        std::fs::create_dir_all(&path)?;
        path.push("duc.db");
        path
    };

    let db = Database::open(&db_path)?;

    // Clear existing data or create new
    if !cmd.force {
        db.clear()?;
    }

    // Scan and index each path
    for path in cmd.paths {
        let canonical_path = std::fs::canonicalize(&path)?;
        let result = scan::scan_directory(&canonical_path)?;

        // Insert results into database
        for (dir_path, (size_actual, size_apparent, count, files)) in result.dirs {
            let dirs = count - files;
            let path_str = dir_path.to_string_lossy().to_string();

            let entry = DirEntry {
                path: path_str,
                size_actual,
                size_apparent,
                count,
                files,
                dirs,
                mtime: Local::now().timestamp() as u64,
            };

            db.insert_dir(&entry)?;
        }
    }

    Ok(())
}
