use crate::db::Database;
use crate::format;
use std::path::PathBuf;
use chrono::{DateTime, Local, NaiveDateTime, Utc};

impl ParseArgs for InfoCmd {
    fn parse_args(args: &[String]) -> Self {
        let mut cmd = InfoCmd {
            apparent: false,
            bytes: false,
            database: None,
            histogram: false,
        };

        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "-a" | "--apparent" => cmd.apparent = true,
                "-b" | "--bytes" => cmd.bytes = true,
                "-d" | "--database" => {
                    i += 1;
                    if i < args.len() {
                        cmd.database = Some(PathBuf::from(&args[i]));
                    }
                }
                "-H" | "--histogram" => cmd.histogram = true,
                _ => {}
            }
            i += 1;
        }

        cmd
    }
}

pub fn run(mut cmd: InfoCmd, global_db: Option<PathBuf>) -> Result<(), Box<dyn std::error::Error>> {
    let db_path = if let Some(db) = cmd.database.take() {
        db
    } else if let Some(db) = global_db {
        db
    } else {
        let mut path = dirs::home_dir().ok_or("Could not find home directory")?;
        path.push(".cache");
        path.push("duc");
        path.push("duc.db");
        path
    };

    let db = Database::open(&db_path)?;

    let entries = db.get_all_entries()?;

    println!("Date       Time       Files    Dirs    Size Path");

    for (path, size_actual, _size_apparent) in entries {
        let size = if cmd.bytes { size_actual } else { size_actual };
        let size_str = if cmd.bytes {
            format!("{}", size)
        } else {
            format::format_size(size, false)
        };

        // Get mtime
        if let Ok(Some(entry)) = db.get_dir(&path) {
            let timestamp = entry.mtime as i64;
            let naive = NaiveDateTime::from_timestamp_opt(timestamp, 0).unwrap_or_default();
            let datetime: DateTime<Utc> = DateTime::from_naive_utc_and_offset(naive, Utc);
            let local_dt = datetime.with_timezone(&chrono::Local);

            let date_str = local_dt.format("%Y-%m-%d").to_string();
            let time_str = local_dt.format("%H:%M:%S").to_string();

            println!(
                "{} {} {:>7} {:>7} {:>7} {}",
                date_str, time_str, entry.files, entry.dirs, size_str, path
            );
        }
    }

    Ok(())
}
