use crate::commands::{LsCmd, ParseArgs};
use crate::db::Database;
use crate::format;
use std::path::PathBuf;

impl ParseArgs for LsCmd {
    fn parse_args(args: &[String]) -> Self {
        let mut cmd = LsCmd {
            apparent: false,
            ascii: false,
            bytes: false,
            classify: false,
            count: false,
            database: None,
            directory: false,
            dirs_only: false,
            full_path: false,
            graph: false,
            levels: 4,
            name_sort: false,
            recursive: false,
            paths: Vec::new(),
        };

        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "-a" | "--apparent" => cmd.apparent = true,
                "--ascii" => cmd.ascii = true,
                "-b" | "--bytes" => cmd.bytes = true,
                "-F" | "--classify" => cmd.classify = true,
                "--count" => cmd.count = true,
                "-d" | "--database" => {
                    i += 1;
                    if i < args.len() {
                        cmd.database = Some(PathBuf::from(&args[i]));
                    }
                }
                "-D" | "--directory" => cmd.directory = true,
                "--dirs-only" => cmd.dirs_only = true,
                "--full-path" => cmd.full_path = true,
                "-g" | "--graph" => cmd.graph = true,
                "-l" | "--levels" => {
                    i += 1;
                    if i < args.len() {
                        cmd.levels = args[i].parse().unwrap_or(4);
                    }
                }
                "-n" | "--name-sort" => cmd.name_sort = true,
                "-R" | "--recursive" => cmd.recursive = true,
                _ => {
                    if !args[i].starts_with("-") {
                        cmd.paths.push(PathBuf::from(&args[i]));
                    }
                }
            }
            i += 1;
        }

        cmd
    }
}

pub fn run(mut cmd: LsCmd, global_db: Option<PathBuf>) -> Result<(), Box<dyn std::error::Error>> {
    let db_path = if let Some(db) = cmd.database.take() {
        db
    } else if let Some(db) = global_db {
        db
    } else {
        let mut path = dirs::home_dir().ok_or("Could not find home directory")?;
        path.push(".cache");
        path.push("duc");
        path.push("duc.db");
        path
    };

    let db = Database::open(&db_path)?;

    if cmd.paths.is_empty() {
        cmd.paths.push(PathBuf::from("."));
    }

    for path in cmd.paths {
        let path_str = path.to_string_lossy().to_string();

        // Get children
        let mut children = db.get_direct_children(&path_str)?;

        // Sort
        if cmd.name_sort {
            children.sort_by(|a, b| a.path.cmp(&b.path));
        } else {
            children.sort_by(|a, b| b.size_actual.cmp(&a.size_actual));
        }

        // Print
        for (idx, child) in children.iter().enumerate() {
            let size = if cmd.bytes {
                child.size_actual.to_string()
            } else {
                format::format_size(child.size_actual, false)
            };

            let name = child.path.split('/').last().unwrap_or(&child.path);

            if cmd.recursive {
                let is_last = idx == children.len() - 1;
                let prefix = if is_last { "╰┬─" } else { "├┬─" };
                println!("{:>6} {} {}", size, prefix, name);

                // Print sub-items
                if let Ok(sub_children) = db.get_direct_children(&child.path) {
                    for (sub_idx, sub_child) in sub_children.iter().enumerate() {
                        let sub_name = sub_child.path.split('/').last().unwrap_or(&sub_child.path);
                        let sub_size = if cmd.bytes {
                            sub_child.size_actual.to_string()
                        } else {
                            format::format_size(sub_child.size_actual, false)
                        };

                        let is_sub_last = sub_idx == sub_children.len() - 1;
                        let sub_prefix = if is_last {
                            if is_sub_last { "  ╰─" } else { "  ├─" }
                        } else {
                            if is_sub_last { "  ╰─" } else { "  ├─" }
                        };
                        println!("{:>6}  {} {}", sub_size, sub_prefix, sub_name);
                    }
                }
            } else {
                println!("{:>6} {}", size, name);
            }
        }
    }

    Ok(())
}
