                    }
                }
                "-x" | "--exclude-files" => cmd.exclude_files = true,
                "-s" | "--min_size" => {
                    i += 1;
                    if i < args.len() {
                        cmd.min_size = Some(args[i].clone());
                    }
                }
                _ => {
                    if !args[i].starts_with("-") {
