        db
    } else {
        let mut path = dirs::home_dir().ok_or("Could not find home directory")?;
        path.push(".cache");
        path.push("duc");
        path.push("duc.db");
        path
    };

    let db = Database::open(&db_path)?;

    if cmd.paths.is_empty() {
        cmd.paths.push(PathBuf::from("."));
    }

