    let path_str = path.to_string_lossy().to_string();

    if let Ok(Some(entry)) = db.get_dir(&path_str) {
        println!("<?xml version=\"1.0\" encoding=\"UTF-8\"?>");
        println!("<duc root=\"{}\" size_apparent=\"{}\" size_actual=\"{}\" count=\"{}\">",
                 path_str, entry.size_apparent, entry.size_actual, entry.count);

        if let Ok(children) = db.get_direct_children(&path_str) {
            for child in children {
                let child_name = child.path.split('/').last().unwrap_or(&child.path);
                println!(" <ent type=\"dir\" name=\"{}\" size_apparent=\"{}\" size_actual=\"{}\" count=\"{}\">",
                         child_name, child.size_apparent, child.size_actual, child.count);

                if let Ok(sub_children) = db.get_direct_children(&child.path) {
                    for sub_child in sub_children {
                        let sub_name = sub_child.path.split('/').last().unwrap_or(&sub_child.path);
                        println!("  <ent name=\"{}\" size_apparent=\"{}\" size_actual=\"{}\" />",
                                 sub_name, sub_child.size_apparent, sub_child.size_actual);
                    }
                }
                println!(" </ent>");
            }
        }

        println!("</duc>");
    }

    Ok(())
}
