use crate::commands::{HistogramCmd, ParseArgs};
use crate::db::Database;
use crate::format;
use std::path::PathBuf;

impl ParseArgs for HistogramCmd {
    fn parse_args(args: &[String]) -> Self {
        let mut cmd = HistogramCmd {
            apparent: false,
            bytes: false,
            database: None,
            base10: false,
        };

        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "-a" | "--apparent" => cmd.apparent = true,
                "-b" | "--bytes" => cmd.bytes = true,
                "-d" | "--database" => {
                    i += 1;
                    if i < args.len() {
                        cmd.database = Some(PathBuf::from(&args[i]));
                    }
                }
                "-t" | "--base10" => cmd.base10 = true,
                _ => {}
            }
            i += 1;
        }

        cmd
    }
}

pub fn run(mut cmd: HistogramCmd, global_db: Option<PathBuf>) -> Result<(), Box<dyn std::error::Error>> {
    let db_path = if let Some(db) = cmd.database.take() {
        db
    } else if let Some(db) = global_db {
        db
    } else {
        let mut path = dirs::home_dir().ok_or("Could not find home directory")?;
        path.push(".cache");
        path.push("duc");
        path.push("duc.db");
        path
    };

    let db = Database::open(&db_path)?;
    let entries = db.get_all_entries()?;

    // Initialize histogram buckets
    let mut histogram = vec![0usize; 48];

    for (_, size_actual, _) in entries {
        if size_actual > 0 {
            let bucket = if cmd.base10 {
                (size_actual as f64).log10().ceil() as usize
            } else {
                (size_actual as f64).log2().ceil() as usize
            };
            if bucket < histogram.len() {
                histogram[bucket] += 1;
            }
        }
    }

    // Print histogram
    println!("Path: {:?}", db_path);
    println!("Bkt       Size      Count");

    for (bucket, count) in histogram.iter().enumerate() {
        let size = 1u64 << bucket;
        let size_str = format::format_size(size, false);
        println!("{:>3} {:>10} {:>10}", bucket, size_str, count);
    }

    Ok(())
}
