        if let Ok(Some(entry)) = db.get_dir(&path) {
            let timestamp = entry.mtime as i64;
            let secs_per_day = 86400;
            let days_since_epoch = timestamp / secs_per_day;
            let secs_today = timestamp % secs_per_day;

            // Very rough approximation of date/time formatting
            // Would need proper date library for accurate formatting
            let year = 1970 + (days_since_epoch / 365);
            let day_of_year = days_since_epoch % 365;
            let month = (day_of_year / 30) + 1;
            let day = (day_of_year % 30) + 1;

            let hour = secs_today / 3600;
            let min = (secs_today % 3600) / 60;
            let sec = secs_today % 60;

            println!(
                "{:04}-{:02}-{:02} {:02}:{:02}:{:02} {:>7} {:>7} {:>7} {}",
                year, month, day, hour, min, sec, entry.files, entry.dirs, size_str, path
            );
        }
    }

    Ok(())
}
