use crate::commands;
use crate::db::Database;
use crate::format;
use std::collections::HashMap;

pub fn run(args: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let (opts, mut paths) = commands::parse_args(&args[1..]);

    if paths.is_empty() {
        paths.push(".".to_string());
    }

    let db_path = commands::get_db_path(&opts)?;
    let db = Database::open(&db_path)?;

    let recursive = commands::has_option(&opts, &["R", "recursive"]);
    let bytes = commands::has_option(&opts, &["b", "bytes"]);

    for path in paths {
        let path_str = path;

        // Get children
        let mut children = db.get_direct_children(&path_str)?;

        // Sort
        if commands::has_option(&opts, &["n", "name-sort"]) {
            children.sort_by(|a, b| a.path.cmp(&b.path));
        } else {
            children.sort_by(|a, b| b.size_actual.cmp(&a.size_actual));
        }

        // Print
        for (idx, child) in children.iter().enumerate() {
            let size = if bytes {
                child.size_actual.to_string()
            } else {
                format::format_size(child.size_actual, false)
            };

            let name = child.path.split('/').last().unwrap_or(&child.path);

            if recursive {
                let is_last = idx == children.len() - 1;
                let prefix = if is_last { "╰┬─" } else { "├┬─" };
