use crate::commands;
use crate::db::Database;
use std::collections::HashMap;

fn escape_xml(s: &str) -> String {
    s.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace("\"", "&quot;")
        .replace("'", "&apos;")
}

pub fn run(args: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let (opts, mut paths) = commands::parse_args(&args[1..]);

    if paths.is_empty() {
        paths.push(".".to_string());
    }

    let db_path = commands::get_db_path(&opts)?;
    let db = Database::open(&db_path)?;

    let path = &paths[0];

    if let Ok(Some(entry)) = db.get_dir(&path) {
        println!("<?xml version=\"1.0\" encoding=\"UTF-8\"?>");
        println!("<duc root=\"{}\" size_apparent=\"{}\" size_actual=\"{}\" count=\"{}\">",
                 escape_xml(path), entry.size_apparent, entry.size_actual, entry.count);

        if let Ok(children) = db.get_direct_children(&path) {
            for child in children {
                let child_name = child.path.split('/').last().unwrap_or(&child.path);
                println!(" <ent type=\"dir\" name=\"{}\" size_apparent=\"{}\" size_actual=\"{}\" count=\"{}\">",
                         escape_xml(child_name), child.size_apparent, child.size_actual, child.count);

                if let Ok(sub_children) = db.get_direct_children(&child.path) {
                    for sub_child in sub_children {
                        let sub_name = sub_child.path.split('/').last().unwrap_or(&sub_child.path);
                        println!("  <ent name=\"{}\" size_apparent=\"{}\" size_actual=\"{}\" />",
                                 escape_xml(sub_name), sub_child.size_apparent, sub_child.size_actual);
                    }
                }
                println!(" </ent>");
            }
        }

        println!("</duc>");
    }

    Ok(())
}
