        .replace("\"", "\\\"")
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t")
}

pub fn run(args: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let (opts, mut paths) = commands::parse_args(&args[1..]);

    if paths.is_empty() {
        paths.push(".".to_string());
    }

    let db_path = commands::get_db_path(&opts)?;
    let db = Database::open(&db_path)?;

    let path = &paths[0];

    if let Ok(Some(entry)) = db.get_dir(&path) {
        println!("{{");
        println!("  \"name\": \"{}\",", escape_json(path));
        println!("  \"count\": {},", entry.count);
        println!("  \"size_apparent\": {},", entry.size_apparent);
        println!("  \"size_actual\": {},", entry.size_actual);
        println!("  \"children\": [");

        if let Ok(children) = db.get_direct_children(&path) {
            for (idx, child) in children.iter().enumerate() {
                let child_name = child.path.split('/').last().unwrap_or(&child.path);
                print!("    {{\n      \"name\": \"{}\",\n", escape_json(child_name));
                print!("      \"count\": {},\n", child.count);
                print!("      \"size_apparent\": {},\n", child.size_apparent);
                print!("      \"size_actual\": {},\n", child.size_actual);
                print!("      \"children\": [");

                if let Ok(sub_children) = db.get_direct_children(&child.path) {
                    for (sub_idx, sub_child) in sub_children.iter().enumerate() {
                        let sub_name = sub_child.path.split('/').last().unwrap_or(&sub_child.path);
                        print!("\n        {{\n          \"name\": \"{}\",\n", escape_json(sub_name));
                        print!("          \"size_apparent\": {},\n", sub_child.size_apparent);
                        print!("          \"size_actual\": {}\n", sub_child.size_actual);
                        if sub_idx == sub_children.len() - 1 {
                            print!("        }}\n      ");
                        } else {
                            print!("        }},\n      ");
                        }
                    }
                }

                print!("]\n    }}");
                if idx < children.len() - 1 {
                    print!(",\n");
                } else {
                    print!("\n");
                }
            }
        }

        println!("  ]");
        println!("}}");
    }

    Ok(())
}
