cat > /workspace/src/commands/histogram.rs << 'EOF'
use crate::commands;
use crate::db::Database;
use crate::format;
use std::collections::HashMap;

pub fn run(args: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let (opts, _paths) = commands::parse_args(&args[1..]);

    let db_path = commands::get_db_path(&opts)?;
    let db = Database::open(&db_path)?;
    let entries = db.get_all_entries()?;

    // Initialize histogram buckets
    let mut histogram = vec![0usize; 48];

    for (_, size_actual, _) in entries {
        if size_actual > 0 {
            let bucket = (64 - size_actual.leading_zeros()) as usize;
            if bucket < histogram.len() {
                histogram[bucket] += 1;
            }
        }
    }

    // Print histogram
    println!("Path: {:?}", db_path);
    println!("Bkt       Size      Count");

    for (bucket, count) in histogram.iter().enumerate() {
        let size = 1u64 << bucket;
        let size_str = format::format_size(size, false);
        println!("{:>3} {:>10} {:>10}", bucket, size_str, count);
    }

    Ok(())
}
EOF

