use std::path::{PathBuf, Path};
use std::fs;
use std::io::{Read, Write};
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct DirEntry {
    pub path: String,
    pub size_actual: u64,
    pub size_apparent: u64,
    pub count: u64,
    pub files: u64,
    pub dirs: u64,
    pub mtime: u64,
}

pub struct Database {
    path: PathBuf,
    data: HashMap<String, DirEntry>,
}

impl Database {
    pub fn open(path: &PathBuf) -> Result<Self, Box<dyn std::error::Error>> {
        let mut data = HashMap::new();

        // Try to load existing data
        if path.exists() {
            if let Ok(content) = fs::read_to_string(path) {
                if let Ok(parsed_data) = Self::parse_db(&content) {
