pub mod help;
pub mod index;
pub mod info;
pub mod ls;
pub mod topn;
pub mod xml;
pub mod json;
pub mod histogram;

use std::path::PathBuf;
use std::collections::HashMap;
use std::env;

pub fn parse_args(args: &[String]) -> (HashMap<String, String>, Vec<String>) {
    let mut options = HashMap::new();
    let mut paths = Vec::new();
    let mut i = 0;

    while i < args.len() {
        let arg = &args[i];

        if arg.starts_with("--") {
            let key_val: Vec<&str> = arg[2..].split('=').collect();
            if key_val.len() == 2 {
                options.insert(key_val[0].to_string(), key_val[1].to_string());
            } else if key_val.len() == 1 {
                if i + 1 < args.len() && !args[i + 1].starts_with("-") {
                    i += 1;
                    options.insert(key_val[0].to_string(), args[i].clone());
                } else {
                    options.insert(key_val[0].to_string(), "true".to_string());
                }
            }
        } else if arg.starts_with("-") && arg.len() > 1 {
            let chars: Vec<char> = arg[1..].chars().collect();
            if chars.len() == 1 {
                let key = chars[0].to_string();
                if i + 1 < args.len() && !args[i + 1].starts_with("-") {
                    i += 1;
                    options.insert(key, args[i].clone());
                } else {
                    options.insert(key, "true".to_string());
                }
            } else {
                // Handle combined flags like -abc
                for ch in chars {
                    options.insert(ch.to_string(), "true".to_string());
                }
            }
        } else {
            paths.push(arg.clone());
        }

        i += 1;
    }

    (options, paths)
}

pub fn get_option(opts: &HashMap<String, String>, keys: &[&str]) -> Option<String> {
    for key in keys {
        if let Some(val) = opts.get(*key) {
            return Some(val.clone());
        }
    }
    None
}

pub fn has_option(opts: &HashMap<String, String>, keys: &[&str]) -> bool {
    for key in keys {
        if opts.contains_key(*key) {
            return true;
        }
    }
    false
}

pub fn get_db_path(opts: &HashMap<String, String>) -> Result<PathBuf, String> {
    if let Some(db_path) = get_option(opts, &["d", "database"]) {
        Ok(PathBuf::from(db_path))
    } else {
        let home_dir = env::var_os("HOME")
            .and_then(|h| if h.is_empty() { None } else { Some(h) })
            .ok_or_else(|| "Could not find home directory".to_string())?;

        let mut path = PathBuf::from(home_dir);
        path.push(".cache");
        path.push("duc");
        std::fs::create_dir_all(&path).ok();
        path.push("duc.db");
        Ok(path)
    }
}
