use crate::commands;
use crate::db::DirEntry;
use crate::scan;
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};

pub fn run(args: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let (opts, paths) = commands::parse_args(&args[1..]);

    if paths.is_empty() {
        return Err("No paths specified".into());
    }

    let db_path = commands::get_db_path(&opts)?;

    let db = crate::db::Database::open(&db_path)?;

    // Clear existing data 
    if !commands::has_option(&opts, &["f", "force"]) {
        db.clear()?;
    }

    // Scan and index each path
    for path in paths {
        let path_buf = PathBuf::from(&path);
        let canonical_path = std::fs::canonicalize(&path_buf)?;
        let result = scan::scan_directory(&canonical_path)?;

        // Insert results into database
        for (dir_path, (size_actual, size_apparent, count, files)) in result.dirs {
            let dirs = count - files;
            let path_str = dir_path.to_string_lossy().to_string();

            let now = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs();

            let entry = DirEntry {
                path: path_str,
                size_actual,
                size_apparent,
                count,
                files,
                dirs,
                mtime: now,
            };

            db.insert_dir(&entry)?;
        }
    }

    Ok(())
}
