use std::path::PathBuf;
use std::fs;
use std::collections::HashMap;
use std::cell::RefCell;

#[derive(Debug, Clone)]
pub struct DirEntry {
    pub path: String,
    pub size_actual: u64,
    pub size_apparent: u64,
    pub count: u64,
    pub files: u64,
    pub dirs: u64,
    pub mtime: u64,
}

pub struct Database {
    path: PathBuf,
    data: RefCell<HashMap<String, DirEntry>>,
}

impl Database {
    pub fn open(path: &PathBuf) -> Result<Self, Box<dyn std::error::Error>> {
        let mut data = HashMap::new();

        // Try to load existing data
        if path.exists() {
            if let Ok(content) = fs::read_to_string(path) {
                if let Ok(parsed_data) = Self::parse_db(&content) {
                    data = parsed_data;
                }
            }
        } else {
            // Create parent directories if they don't exist
            if let Some(parent) = path.parent() {
                fs::create_dir_all(parent).ok();
            }
        }

        Ok(Database {
            path: path.clone(),
            data: RefCell::new(data),
        })
    }

    fn parse_db(content: &str) -> Result<HashMap<String, DirEntry>, Box<dyn std::error::Error>> {
        let mut map = HashMap::new();

        for line in content.lines() {
            if line.trim().is_empty() {
                continue;
            }

            let parts: Vec<&str> = line.split('\t').collect();
            if parts.len() >= 7 {
                let entry = DirEntry {
                    path: parts[0].to_string(),
                    size_actual: parts[1].parse().unwrap_or(0),
                    size_apparent: parts[2].parse().unwrap_or(0),
                    count: parts[3].parse().unwrap_or(0),
                    files: parts[4].parse().unwrap_or(0),
                    dirs: parts[5].parse().unwrap_or(0),
                    mtime: parts[6].parse().unwrap_or(0),
                };
                map.insert(entry.path.clone(), entry);
            }
        }

        Ok(map)
    }

    fn to_string(&self) -> String {
        let data = self.data.borrow();
        let mut lines = Vec::new();
        for (_path, entry) in data.iter() {
            lines.push(format!(
                "{}\t{}\t{}\t{}\t{}\t{}\t{}",
                entry.path,
                entry.size_actual,
                entry.size_apparent,
                entry.count,
                entry.files,
                entry.dirs,
                entry.mtime
            ));
        }
        lines.sort();
        lines.join("\n")
    }

    pub fn insert_dir(&self, entry: &DirEntry) -> Result<(), Box<dyn std::error::Error>> {
        self.data.borrow_mut().insert(entry.path.clone(), entry.clone());
        Ok(())
    }

    pub fn insert_file(&self, path: &str, size_actual: u64, size_apparent: u64) -> Result<(), Box<dyn std::error::Error>> {
        Ok(())
    }

    pub fn get_dir(&self, path: &str) -> Result<Option<DirEntry>, Box<dyn std::error::Error>> {
        Ok(self.data.borrow().get(path).cloned())
    }

    pub fn get_children(&self, path: &str) -> Result<Vec<DirEntry>, Box<dyn std::error::Error>> {
        let prefix = if path.ends_with("/") {
            path.to_string()
        } else {
            format!("{}/", path)
        };

        let data = self.data.borrow();
        let mut result: Vec<DirEntry> = data
            .values()
            .filter(|e| e.path.starts_with(&prefix) && e.path != path)
            .cloned()
            .collect();

        result.sort_by(|a, b| a.path.cmp(&b.path));
        Ok(result)
    }

    pub fn get_direct_children(&self, path: &str) -> Result<Vec<DirEntry>, Box<dyn std::error::Error>> {
        let prefix = if path.ends_with("/") {
            path.to_string()
        } else {
            format!("{}/", path)
        };

        let data = self.data.borrow();
        let mut result = Vec::new();
        for entry in data.values() {
            if entry.path.starts_with(&prefix) && entry.path != path {
                let rel_path = &entry.path[prefix.len()..];
                if !rel_path.contains('/') {
                    result.push(entry.clone());
                }
            }
        }

        result.sort_by(|a, b| b.size_actual.cmp(&a.size_actual));
        Ok(result)
    }

    pub fn get_all_entries(&self) -> Result<Vec<(String, u64, u64)>, Box<dyn std::error::Error>> {
        let data = self.data.borrow();
        let mut result: Vec<_> = data
            .values()
            .map(|e| (e.path.clone(), e.size_actual, e.size_apparent))
            .collect();

        result.sort_by(|a, b| a.0.cmp(&b.0));
        Ok(result)
    }

    pub fn get_top_files(&self) -> Result<Vec<(String, u64)>, Box<dyn std::error::Error>> {
        let data = self.data.borrow();
        let mut result: Vec<_> = data
            .values()
            .map(|e| (e.path.clone(), e.size_actual))
            .collect();

        result.sort_by(|a, b| b.1.cmp(&a.1));
        result.truncate(100);
        Ok(result)
    }

    pub fn set_index_value(&self, name: &str, value: &str) -> Result<(), Box<dyn std::error::Error>> {
        Ok(())
    }

    pub fn get_index_value(&self, name: &str) -> Result<Option<String>, Box<dyn std::error::Error>> {
        Ok(None)
    }

    pub fn clear(&self) -> Result<(), Box<dyn std::error::Error>> {
        self.data.borrow_mut().clear();
        Ok(())
    }

    pub fn save(&self) -> Result<(), Box<dyn std::error::Error>> {
        let content = self.to_string();
        fs::write(&self.path, content)?;
        Ok(())
    }
}

impl Drop for Database {
    fn drop(&mut self) {
        let _ = self.save();
    }
}
