use std::path::PathBuf;
use std::collections::HashMap;
use std::fs;

#[derive(Debug, Clone)]
pub struct ScanResult {
    pub dirs: HashMap<PathBuf, (u64, u64, u64, u64)>, // (size_actual, size_apparent, count, files)
}

pub fn scan_directory(root: &PathBuf) -> std::io::Result<ScanResult> {
    let mut dirs: HashMap<PathBuf, (u64, u64, u64, u64)> = HashMap::new();

    // Add root
    dirs.insert(root.clone(), (0, 0, 0, 0));

    walk_dir(root, root, &mut dirs)?;

    Ok(ScanResult { dirs })
}

fn walk_dir(
    current: &PathBuf,
    root: &PathBuf,
    dirs: &mut HashMap<PathBuf, (u64, u64, u64, u64)>,
) -> std::io::Result<()> {
    match fs::read_dir(current) {
        Ok(entries) => {
            for entry in entries {
                if let Ok(entry) = entry {
                    let path = entry.path();
                    if let Ok(metadata) = entry.metadata() {
                        let size = metadata.len();
                        let apparent_size = if metadata.is_dir() { 
                            4096 
                        } else { 
                            ((size + 4095) / 4096) * 4096 
                        };

                        // Only process non-directories here
                        if !metadata.is_dir() {
                            // Update all parent directories
                            let mut current_path = path.clone();
                            while current_path.pop() {
                                if current_path.starts_with(root) || current_path == *root {
                                    let entry = dirs.entry(current_path.clone()).or_insert((0, 0, 0, 0));
                                    entry.0 += size;
                                    entry.1 += apparent_size;
                                    entry.2 += 1;
                                    entry.3 += 1;
                                }
                            }

                            // Update root
                            let entry = dirs.entry(root.clone()).or_insert((0, 0, 0, 0));
                            entry.0 += size;
                            entry.1 += apparent_size;
                            entry.2 += 1;
                            entry.3 += 1;
                        } else {
                            // It's a directory, add it to dirs map and recurse
                            dirs.insert(path.clone(), (0, 0, 0, 0));
                            let _ = walk_dir(&path, root, dirs);
                        }
                    }
                }
            }
        }
        Err(_) => {}
    }

    Ok(())
}
