pub fn run(args: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let (opts, mut paths) = commands::parse_args(&args[1..]);

    if paths.is_empty() {
        paths.push(".".to_string());
    }

    let db_path = commands::get_db_path(&opts)?;
    let db = Database::open(&db_path)?;

    let recursive = commands::has_option(&opts, &["R", "recursive"]);
    let bytes = commands::has_option(&opts, &["b", "bytes"]);
    let apparent = commands::has_option(&opts, &["a", "apparent"]);

    for path in paths {
        let path_str = path;

        // Get children
        let mut children = db.get_direct_children(&path_str)?;

        // Sort
        if commands::has_option(&opts, &["n", "name-sort"]) {
            children.sort_by(|a, b| a.path.cmp(&b.path));
        } else {
            children.sort_by(|a, b| b.size_actual.cmp(&a.size_actual));
        }

        // Print
        for (idx, child) in children.iter().enumerate() {
            // Use apparent size by default, actual if -a flag
            let size_to_use = if apparent {
                child.size_actual
            } else {
                child.size_apparent
            };

            let size = if bytes {
                size_to_use.to_string()
            } else {
                format::format_size(size_to_use, false)
            };

            let name = child.path.split('/').last().unwrap_or(&child.path);

            if recursive {
                let is_last = idx == children.len() - 1;
                let prefix = if is_last { "╰┬─" } else { "├┬─" };
                println!("{:>6} {} {}", size, prefix, name);

                // Print sub-items
                if let Ok(sub_children) = db.get_direct_children(&child.path) {
                    for (sub_idx, sub_child) in sub_children.iter().enumerate() {
                        let sub_name = sub_child.path.split('/').last().unwrap_or(&sub_child.path);
                        let sub_size_to_use = if apparent {
                            sub_child.size_actual
                        } else {
                            sub_child.size_apparent
                        };
                        let sub_size = if bytes {
                            sub_size_to_use.to_string()
                        } else {
                            format::format_size(sub_size_to_use, false)
                        };

                        let is_sub_last = sub_idx == sub_children.len() - 1;
                        let sub_prefix = if is_last {
                            if is_sub_last { "  ╰─" } else { "  ├─" }
                        } else {
                            if is_sub_last { "  ╰─" } else { "  ├─" }
                        };
                        println!("{:>6}  {} {}", sub_size, sub_prefix, sub_name);
                    }
                }
            } else {
                println!("{:>6} {}", size, name);
            }
        }
    }

    Ok(())
}
