use std::path::PathBuf;
use std::collections::HashMap;
use std::fs;

#[derive(Debug, Clone)]
pub struct ScanResult {
    pub dirs: HashMap<PathBuf, (u64, u64, u64, u64)>, // (size_actual, size_apparent, count, files)
}

pub fn scan_directory(root: &PathBuf) -> std::io::Result<ScanResult> {
    let mut entries: HashMap<PathBuf, (u64, u64, bool)> = HashMap::new(); // path -> (size_actual, size_apparent, is_dir)

    walk_collect(root, &mut entries)?;

    // Now compute directory sizes
    let mut dirs: HashMap<PathBuf, (u64, u64, u64, u64)> = HashMap::new();

    for (path, (size_actual, size_apparent, is_dir)) in &entries {
        if *is_dir {
            let mut dir_size_actual = 0u64;
            let mut dir_size_apparent = 0u64;
            let mut dir_count = 0u64;
            let mut dir_files = 0u64;

            for (other_path, (other_size_actual, other_size_apparent, other_is_dir)) in &entries {
                // Check if other_path is a direct child of path
                if other_path.starts_with(path) && other_path != path {
                    let relative = other_path.strip_prefix(path).unwrap();
                    let rel_str = relative.to_string_lossy();

                    // Count only direct children and files under this directory
                    let parts: Vec<&str> = rel_str.split('/').filter(|s| !s.is_empty()).collect();

                    if parts.len() == 1 {
                        // Direct child
                        dir_size_actual += other_size_actual;
                        dir_size_apparent += other_size_apparent;
                        dir_count += 1;
                        if !other_is_dir {
                            dir_files += 1;
                        }
                    }
                }
            }

            dirs.insert(path.clone(), (dir_size_actual, dir_size_apparent, dir_count, dir_files));
        }
    }

    // Add all directories to the result, even if empty
    for (path, _) in &entries {
        if !dirs.contains_key(path) {
            dirs.insert(path.clone(), (0, 0, 0, 0));
        }
    }

    Ok(ScanResult { dirs })
}

fn walk_collect(
    current: &PathBuf,
    entries: &mut HashMap<PathBuf, (u64, u64, bool)>,
) -> std::io::Result<()> {
    entries.insert(current.clone(), (0, 0, true));

    match fs::read_dir(current) {
        Ok(dir_entries) => {
            for entry in dir_entries {
                if let Ok(entry) = entry {
                    let path = entry.path();
                    if let Ok(metadata) = entry.metadata() {
                        let size = metadata.len();
                        let apparent_size = ((size + 4095) / 4096) * 4096;

                        if metadata.is_dir() {
                            walk_collect(&path, entries)?;
                        } else {
                            entries.insert(path, (size, apparent_size, false));
                        }
                    }
                }
            }
        }
        Err(_) => {}
    }

    Ok(())
}
